import React, { useEffect, useMemo, useState } from 'react';
import { Alert, Box, Button, Typography } from '@mui/material';
import { Link as RouterLink, useLocation } from 'react-router-dom';
import ManufacturingWorkflowPlanner from './ManufacturingWorkflowPlanner';
import ApiService from '../services/api';
import { ProfileCompletenessCard } from './shared/ProfileCompletenessCard';
import { OnboardingProgressBar } from './shared/OnboardingProgressBar';
import { DashboardNextBestAction } from './dashboard/DashboardNextBestAction';
import { computeMsmeProfileCompleteness, deriveNextBestAction } from '../utils/sustainabilityUx';

const OperationsPage: React.FC = () => {
  const location = useLocation();
  const [profile, setProfile] = useState<Record<string, unknown> | null>(null);

  useEffect(() => {
    ApiService.getMSMEProfile()
      .then((res) => {
        const data = res?.data || res;
        if (data && typeof data === 'object') {
          setProfile(data as Record<string, unknown>);
        }
      })
      .catch(() => setProfile(null));
  }, []);

  const fromLocation = (location.state as { from?: { pathname?: string } } | null)?.from;
  const fromPath = fromLocation?.pathname;
  const showWorkflowGateHint =
    Boolean(fromPath) &&
    fromPath !== '/operations' &&
    !fromPath?.startsWith('/msme-profile');

  const profileCompleteness = useMemo(
    () => computeMsmeProfileCompleteness(profile),
    [profile]
  );

  const nextAction = useMemo(
    () =>
      deriveNextBestAction({
        hasProfile: profileCompleteness.score >= 55,
        hasDocuments: false,
        hasAssessment: false,
        carbonScore: 0,
      }),
    [profileCompleteness.score]
  );

  return (
    <Box>
      <OnboardingProgressBar
        activeStep={1}
        subtitle="Step 2 of 2 — define units and scope data, then save your workflow."
      />

      {showWorkflowGateHint && (
        <Alert severity="info" sx={{ mb: 2 }}>
          Complete the operations workflow below to unlock the rest of the app (for example{' '}
          {fromPath === '/dashboard' ? 'the dashboard' : `“${fromPath}”`}). You can return there when the planner is
          finished.
        </Alert>
      )}
      <Typography variant="body1" color="text.secondary" sx={{ mb: 2, maxWidth: 900 }}>
        Work through each section in order: add your units, then Scope 1–3 activity data, and save on Review.
        Listed-company and GHG organizational boundary fields live on{' '}
        <Button component={RouterLink} to="/msme-profile" size="small" sx={{ px: 0.5, minWidth: 0, verticalAlign: 'baseline' }}>
          Profile
        </Button>
        {' '}when you need them for BRSR filing.
      </Typography>

      {profile && (
        <>
          <ProfileCompletenessCard
            result={profileCompleteness}
            title="Company profile completeness"
            actionPath="/msme-registration"
            actionLabel="Edit company profile"
          />
          {profileCompleteness.score < 85 && (
            <DashboardNextBestAction action={nextAction} />
          )}
        </>
      )}

      <ManufacturingWorkflowPlanner isEmbeddedInOperationsPage />
    </Box>
  );
};

export default OperationsPage;
